    wire signed [31:0] sum_b = (p4 + p5) + (p6 + p7);

    always @(posedge clk) begin
        if (rst) begin
            for (i = 0; i < 8; i = i + 1)
                d[i] <= 16'sd0;
            sum_pipe0_a <= 32'sd0;
            sum_pipe0_b <= 32'sd0;
            sum_pipe1 <= 32'sd0;
            y_out <= 32'sd0;
